function closedLoRaAS923(o){const T=LoRaAS923Three,g=o.geometry,p=g.attributes.position,ix=g.index,keys=[],edges=new Map();let volume=0;for(let i=0;i<p.count;i++)keys.push([p.getX(i),p.getY(i),p.getZ(i)].map(v=>Math.round(v*1e5)).join(','));for(let k=0;k<(ix?.count??p.count);k+=3){const ids=[0,1,2].map(j=>ix?ix.getX(k+j):k+j),v=ids.map(i=>new T.Vector3().fromBufferAttribute(p,i));volume+=v[0].dot(v[1].clone().cross(v[2]))/6;for(let j=0;j<3;j++){const a=keys[ids[j]],b=keys[ids[(j+1)%3]];if(a===b)continue;const key=a<b?a+'|'+b:b+'|'+a,e=edges.get(key)??[0,0];e[0]++;e[1]+=a<b?1:-1;edges.set(key,e);}}assert.ok(volume>1e-9,'AS923 positive material volume:'+o.name);assert.ok([...edges.values()].every(([n,d])=>n===2&&d===0),'AS923 closed coherent directed material:'+o.name);assert.equal(o.material.side,T.FrontSide);return(ix?.count??p.count)/3;}
