export function checkLoRaWANEU868Runtime(host,u,prefix,events){u.root;tick(host);const a=u.lorawanEU868Assembly,port=u.get('antenna'),initial=port.module,created=initial?null:new LoRaEU868Antenna({foldDeg:90});if(created)port.attach(created);const antenna=port.module,joint=antenna.get('fold'),aa=antenna.eu868AntennaAssembly,restAngle=joint.angleDeg,body=physical(u,[antenna.root]),fixed=physical(u,[joint.object3d]),ports=frames(u),peer=physical(host,[u.root]),start=events.length;let disposed=0;try{const before=physical(antenna),moving=physical(joint.object3d),next=restAngle===90?0:90;joint.set({angleDeg:next,durationMs:200});host.update(.05);assert.ok(joint.angleDeg>0&&joint.angleDeg<90);assert.notEqual(physical(joint.object3d),moving);assert.equal(physical(u,[joint.object3d]),fixed,'Only real accessoryhub/arm/blade move;SMAcoupling/metal/PCB/film remain');assert.equal(physical(u,[antenna.root]),body);assert.equal(frames(u),ports);assert.equal(physical(host,[u.root]),peer);tick(host);assert.equal(joint.angleDeg,next);assert.equal(joint.getState().transitioning,false);let shape=physical(antenna);host.update(.5);assert.equal(physical(antenna),shape,'No automatic fold/servo/RF motion');assert.equal(events.length,start,'External actual joint pose has no input echo');for(const angleDeg of[-1,91,NaN]){const state=joint.getState();assert.throws(()=>joint.set({angleDeg}));assert.deepEqual(joint.getState(),state);}assert.throws(()=>joint.set({rpm:1}));assert.equal(events.length,start);host.handle({type:'joint',target:target(prefix,'antenna/fold'),angleDeg:restAngle});assert.equal(physical(antenna),before,'All accessory attrs/index/world restore at actual initial angle');assert.equal(physical(u,[joint.object3d]),fixed);const resources=physical(antenna),removed=port.detach({dispose:false});assert.ok(removed===antenna);assert.equal(physical(u),body);assert.equal(frames(u),ports);assert.equal(physical(host,[u.root]),peer);port.attach(antenna);host.update(0);assert.equal(physical(antenna),resources,'Actual SMA detach/reattach restores joint state and all attrs/index/world');assert.equal(events.length,start);for(const id of['grove','antenna'])for(const type of['uart','at','lorawan','rf','power','firmware','sensor','led','button','i2c','joint'])assert.throws(()=>host.handle({type,target:target(prefix,id),value:1}));assert.equal(events.length,start);assert.equal(physical(u,[antenna.root]),body);assert.equal(frames(u),ports);return{ownControls:0,ownLeds:0,ownJoints:0,accessoryJoint:'antenna/fold',actualPartialFold:true,inferredDisplayRangeDeg:[0,90],onlyRealHubArmBladeMove:true,fixedCouplingSmaNativePcbFilmPortsAndPeersRetained:true,externalJointNoEcho:true,noContinuousRpmOrAutomaticRFBehavior:true,allPhysicalAttributesIndexWorldRestored:true,realSmaAccessoryDetachRestore:true,initialAccessory:!!initial,createdProbeAccessoryDisposed:!!created};}finally{joint.set({angleDeg:restAngle});if(created){if(created.attachedTo)created.attachedTo.detach({dispose:false});const observe=observeDisposal(created.root);created.dispose();disposed=observe();assert.ok(disposed>0);}assert.ok(port.module===initial);}}

